// План: specs/deals.md, блок 1. Кейсы: .qa/tests/deals/REL-001…004. Тикет #6a86f7cd444d05eea4a45199.
// Несколько ролей: נותן שירות (0500000005, «שירה כהן») просит освобождение, клиент (0500000004, «יונתן לוי») подтверждает.
// Нужна сделка в נאמנות без запроса: QA_RELEASE_DEAL_ID=<id> или QA_ALLOW_DEPOSIT=1 (создаст QA-AUTO-שחרור …).
// Освобождение переводит тестовые деньги client → provider → не @prod-safe. Один прогон (@android), без повторов.
import { test, expect } from '../../fixtures';
import type { Page, Locator } from '@playwright/test';
import { getEscrowDeal, waitWithReload, openTab, historyEntries, TODAY_TIME, PROVIDER_NAME } from '../disputes/helpers';

test.describe.configure({ mode: 'serial', retries: 0 });

const DECLARATION = 'אני מאשר/ת שהשירות הושלם לפי התנאים שסוכמו.';
const PROVIDER_WAITING = 'ממתין לאישור הלקוח';
const CLIENT_WAITING = 'ממתין לאישור תשלום';
const COMPLETED = 'עסקה הושלמה';

let dealId = '';
let dealTitle = '';
let dealAmount = 0;
let providerBalanceBefore = 0;

const shekels = (s: string) => Number(s.replace(/[^\d.]/g, ''));

/** «סכום העסקה» на вкладке «פרטי עסקה». */
async function readDealAmount(page: Page): Promise<number> {
  const body = await page.locator('body').innerText();
  const m = body.match(/סכום העסקה\s*\n?\s*(₪[\d,.]+)/);
  if (!m) throw new Error('Не найдена «סכום העסקה» на странице сделки');
  return shekels(m[1]);
}

/** «היתרה שלך» на главной (S-11 AC2). */
async function readAvailableBalance(page: Page): Promise<number> {
  await page.goto('/wallet');
  await expect(page.getByText('היתרה שלך').first()).toBeVisible();
  const body = await page.locator('body').innerText();
  const m = body.match(/היתרה שלך\s*\n?\s*(₪[\d,.]+)/);
  if (!m) throw new Error('Не найдена сумма «היתרה שלך» на /wallet');
  return shekels(m[1]);
}

/** Чип в карточке суммы + «סטטוס תשלום» (F-29 AC7, F-38 AC4): текст статуса виден минимум дважды. */
async function expectStatus(page: Page, status: string, label: string, min = 2) {
  await expect
    .poll(() => page.getByText(status, { exact: true }).count(), { message: `${label}: «${status}» в чипе и в «סטטוס תשלום»` })
    .toBeGreaterThanOrEqual(min);
}

const declaration = (page: Page): Locator => page.getByRole('checkbox').last();

test.describe('עסקה בטוחה — שחרור כסף בהסכמה דו-צדדית', () => {
  test('נותן שירות: שיט "בקשת שחרור כסף" — הכפתור נעול עד סימון ההצהרה @android #6a86f7cd444d', async ({ asUser }) => {
    const client = await asUser('client');
    const provider = await asUser('provider');
    ({ id: dealId, title: dealTitle } = await getEscrowDeal(client, provider, 'RELEASE'));

    await provider.goto(`/deals/${dealId}`);
    await expect(provider.getByText('הכסף שמור בנאמנות').first()).toBeVisible();
    await expect(provider.getByText('שמור בנאמנות', { exact: true }).first()).toBeVisible();
    await expect(provider.getByRole('button', { name: 'פתיחת מחלוקת' })).toBeVisible();
    dealAmount = await readDealAmount(provider);
    // Для заранее подготовленной сделки название задаётся QA_RELEASE_DEAL_TITLE (нужно для строки в «עסקאות» и уведомления).
    if (!dealTitle) dealTitle = process.env.QA_RELEASE_DEAL_TITLE ?? '';

    await provider.getByRole('button', { name: 'בקשה לקבלת הכסף' }).click();
    await expect(provider.getByText('בקשת שחרור כסף', { exact: true })).toBeVisible();
    await expect(provider.getByText('לאחר שליחת הבקשה, הצד השני יקבל התראה ויוכל לאשר את שחרור הכסף.')).toBeVisible();
    await expect(provider.getByText(DECLARATION)).toBeVisible();

    const send = provider.getByRole('button', { name: 'שליחת בקשה' }).last();
    await expect(send, 'без галочки «שליחת בקשה» заблокирована').toBeDisabled();
    await declaration(provider).click();
    await expect(send, 'после отметки — активна').toBeEnabled();
    await declaration(provider).click();
    await expect(send, 'после снятия — снова заблокирована').toBeDisabled();

    // Закрыть шит без отправки — статус не меняется.
    await provider.keyboard.press('Escape');
    await provider.goto(`/deals/${dealId}`);
    await expect(provider.getByText('הכסף שמור בנאמנות').first()).toBeVisible();
    await expect(provider.getByText(PROVIDER_WAITING, { exact: true })).toHaveCount(0);
  });

  test('אחרי "שליחת בקשה": אצל נותן השירות "ממתין לאישור הלקוח", אין אישור עצמי @android #6a86f7cd444d', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const provider = await asUser('provider');
    await provider.goto(`/deals/${dealId}`);
    await provider.getByRole('button', { name: 'בקשה לקבלת הכסף' }).click();
    await declaration(provider).click();
    await provider.getByRole('button', { name: 'שליחת בקשה' }).last().click();

    for (const pass of ['after send', 'after reload']) {
      if (pass === 'after reload') await provider.reload();
      await expectStatus(provider, PROVIDER_WAITING, `provider ${pass}`);
      // Деньги не освобождены (треб. 6): «עסקה הושלמה» — только подпись шага степпера поставщика, не чип и не статус.
      await expect(provider.getByText(COMPLETED, { exact: true })).toHaveCount(1);
      // Инициатор не может завершить сам.
      await expect(provider.getByRole('button', { name: 'אישור קבלת השירות ותשלום' })).toHaveCount(0);
      await expect(provider.getByRole('button', { name: 'בקשה לקבלת הכסף' })).toHaveCount(0);
    }

    await provider.getByRole('button', { name: 'פעולות נוספות' }).click();
    for (const item of ['עריכת עסקה', 'פתיחת מחלוקת', 'ביטול עסקה']) {
      await expect(provider.getByText(item, { exact: true }).last()).toBeVisible();
    }
    await expect(provider.getByText('אישור קבלת השירות ותשלום')).toHaveCount(0);
    await provider.keyboard.press('Escape');

    // Строка в списке «עסקאות» (коммент программиста 01.10).
    if (!dealTitle) {
      test.info().annotations.push({ type: 'не проверено', description: 'строка в «עסקאות»: задай QA_RELEASE_DEAL_TITLE' });
    } else {
      await provider.goto('/deals');
      const row = provider.getByText(dealTitle, { exact: true }).first();
      await expect(row).toBeVisible();
      const rowText = await row.locator('xpath=ancestor::*[contains(., "₪")][1]').innerText();
      expect(rowText, 'строка сделки в «עסקאות»').toContain(PROVIDER_WAITING);
    }
  });

  test('לקוח: "ממתין לאישור תשלום" והתראה "בקשה לאישור תשלום" @android #6a86f7cd444d', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const client = await asUser('client');

    await client.goto(`/deals/${dealId}`);
    await waitWithReload(client, client.getByRole('button', { name: 'אישור קבלת השירות ותשלום' }));
    await expectStatus(client, CLIENT_WAITING, 'client');
    await expect(client.getByText(PROVIDER_WAITING, { exact: true }), 'у клиента нет формулировки поставщика (F-29 AC4)').toHaveCount(0);

    await client.goto('/notifications');
    await client.getByText('ממתין לפעולה', { exact: true }).first().click();
    const card = client.getByText('בקשה לאישור תשלום', { exact: true }).first();
    await waitWithReload(client, card);
    await expect(client.getByText('הצד השני ביקש לקבל את הכסף. יש לבדוק אם התנאים התקיימו.').first()).toBeVisible();
    if (dealTitle) await expect(client.getByText(new RegExp(dealTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))).first()).toBeVisible();
  });

  test('לקוח מאשר: "עסקה הושלמה" לשני הצדדים, יומן, ללא פעולות כסף, יתרת נותן השירות עלתה @android #6a86f7cd444d', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const client = await asUser('client');
    const provider = await asUser('provider');
    providerBalanceBefore = await readAvailableBalance(provider);

    await client.goto(`/deals/${dealId}`);
    await client.getByRole('button', { name: 'אישור קבלת השירות ותשלום' }).last().click();
    await expect(client.getByText('אישור תשלום והעברת הכסף', { exact: true })).toBeVisible();
    await expect(client.getByText('לאחר שליחת הבקשה, הצד השני יקבל התראה ויוכל לאשר את קבלת הכסף.')).toBeVisible();
    await expect(client.getByText(DECLARATION)).toBeVisible();
    const confirm = client.getByRole('button', { name: 'אישור קבלת השירות ותשלום' }).last();
    await expect(confirm, 'без галочки подтверждение заблокировано').toBeDisabled();
    await declaration(client).click();
    await expect(confirm).toBeEnabled();
    await confirm.click();

    // Обе стороны: завершена, только чтение (F-29 AC3, AC8).
    for (const [who, page] of [['client', client], ['provider', provider]] as const) {
      await page.goto(`/deals/${dealId}`);
      await waitWithReload(page, page.getByText(COMPLETED, { exact: true }).nth(who === 'provider' ? 2 : 1));
      // У поставщика «עסקה הושלמה» есть ещё и подписью шага степпера → минимум 3.
      await expectStatus(page, COMPLETED, who, who === 'provider' ? 3 : 2);
      for (const name of ['פתיחת מחלוקת', 'בקשה לקבלת הכסף', 'אישור קבלת השירות ותשלום']) {
        await expect(page.getByRole('button', { name }), `${who}: нет «${name}»`).toHaveCount(0);
      }
    }
    await expect(provider.getByRole('button', { name: 'פעולות נוספות' }), 'у поставщика меню нет').toHaveCount(0);
    await client.getByRole('button', { name: 'פעולות נוספות' }).click();
    await expect(client.getByText('דירוג נותן השירות', { exact: true })).toBeVisible();
    for (const item of ['עריכת עסקה', 'פתיחת מחלוקת', 'ביטול עסקה']) {
      await expect(client.getByText(item, { exact: true })).toHaveCount(0);
    }
    await client.keyboard.press('Escape');

    // Журнал (F-40, F-29 AC10): новые сверху.
    await client.goto(`/deals/${dealId}`);
    await openTab(client, 'היסטוריה');
    const entries = await historyEntries(client);
    expect(entries[0]).toBe('הכסף שוחרר');
    expect(entries[1]).toMatch(TODAY_TIME);
    expect(entries[2]).toBe(`נשלחה בקשת שחרור כסף על ידי ${PROVIDER_NAME}`);
    expect(entries[3]).toMatch(TODAY_TIME);

    // Деньги у поставщика (треб. 7).
    await expect
      .poll(() => readAvailableBalance(provider), { message: '«היתרה שלך» поставщика выросла на сумму сделки', timeout: 30_000 })
      .toBe(providerBalanceBefore + dealAmount);
  });
});
